import ast, glob, subprocess, sys, json
clis = [f for f in sorted(glob.glob('_tools/*.py')) if "__name__ == '__main__'" in open(f, encoding='utf-8').read().replace('"', "'")]
def lines(f):
    doc = ast.get_docstring(ast.parse(open(f, encoding='utf-8').read())) or ''
    return {k for k in ('Answers:', 'Use:') if any(l.strip().startswith(k) for l in doc.splitlines())}
bare = [f for f in clis if lines(f) != {'Answers:', 'Use:'}]
def top(need):
    r = subprocess.run([sys.executable, '_tools/kbtools.py', need, '--json'], capture_output=True, text=True)
    try:
        return [e.get('tool') for e in json.loads(r.stdout)['entries']][:3]
    except (ValueError, KeyError):
        return []
cases = {'what a sprint item cost in tokens and dollars': 'backlog.py', 'which sessions are running and what is stalled': 'kbmon.py',
         'which docs describe a file I am changing': 'selfdoc.py'}
got = {need: top(need) for need in cases}
ok = not bare and all(cases[n] in got[n] for n in cases)
print('CLIs without Answers:/Use: lines', len(bare), 'of', len(clis), '| top entries', got)
sys.exit(0 if ok else 1)
